svg.script:
(() => {
  const skater = document.getElementById("skater");
  const yaw = document.getElementById("yaw");
  const shadow = document.getElementById("shadow");

  const PI = Math.PI;
  const G = 760;        // Gravity, SVG units / second²
  const R = 205;        // Center-of-mass riding radius
  const OFFSET = 54;    // COM-to-wheel-contact distance
  const AIR_HEIGHT = 80;
  const LIP_Y = 160;
  const launchSpeed = Math.sqrt(2 * G * AIR_HEIGHT);
  const flightTime = 2 * launchSpeed / G;

  let theta = -0.6;
  let direction = 1;
  let facing = 1;
  let side = 1;
  let airborne = false;
  let airTime = 0;

  // Conservation of energy on the ramp:
  // v² = 2g(H + R cos(theta)).
  // This automatically gives faster motion at the bottom.
  function speed(a) {
    return Math.sqrt(
      2 * G * (AIR_HEIGHT + R * Math.max(0, Math.cos(a)))
    );
  }

  function advance(dt) {
    if (airborne) {
      airTime += dt;

      if (airTime >= flightTime) {
        const remainder = airTime - flightTime;
        airborne = false;
        theta = side * PI / 2;
        direction = -side;
        facing *= -1;

        if (remainder > 0) advance(remainder);
      }
      return;
    }

    // Midpoint integration, with short substeps.
    const w0 = direction * speed(theta) / R;
    const midpoint = theta + w0 * dt / 2;
    const next =
      theta + direction * speed(midpoint) / R * dt;

    if (Math.abs(next) >= PI / 2) {
      side = next > 0 ? 1 : -1;
      const boundary = side * PI / 2;
      const fraction = Math.max(0, Math.min(
        1, (boundary - theta) / (next - theta)
      ));

      theta = boundary;
      airborne = true;
      airTime = dt * (1 - fraction);
    } else {
      theta = next;
    }
  }

  function draw() {
    let cx, cy, angle, turn;
    let sx, sy, shadowAngle, shadowOpacity;

    if (airborne) {
      const u = Math.min(1, airTime / flightTime);

      // The COM follows an actual ballistic trajectory.
      // A vertical lip means zero horizontal takeoff velocity.
      cx = 400 + side * R;
      cy = LIP_Y - launchSpeed * airTime
                    + 0.5 * G * airTime * airTime;

      // Level the board near the apex, then realign it
      // with the vertical transition before re-entry.
      const level = Math.sin(PI * u) ** 2;
      angle = -side * PI / 2 * (1 - level);

      // Project a half-turn around the rider's local
      // vertical axis into the side-view illustration.
      const ease = u * u * (3 - 2 * u);
      turn = facing * Math.cos(PI * ease);

      sx = 400 + side * 259;
      sy = LIP_Y;
      shadowAngle = -side * 90;
      shadowOpacity = 0.22 - 0.15 * Math.sin(PI * u);
    } else {
      cx = 400 + R * Math.sin(theta);
      cy = LIP_Y + R * Math.cos(theta);
      angle = -theta;
      turn = facing;

      sx = 400 + 259 * Math.sin(theta);
      sy = LIP_Y + 259 * Math.cos(theta);
      shadowAngle = -theta * 180 / PI;
      shadowOpacity = 0.24;
    }

    // Rotate the rider about the COM, not about the wheels:
    // airborne posture changes must not bend the COM trajectory.
    const bx = cx - OFFSET * Math.sin(angle);
    const by = cy + OFFSET * Math.cos(angle);

    skater.setAttribute("transform",
      `translate(${bx} ${by}) rotate(${angle * 180 / PI})`);

    yaw.setAttribute("transform", `scale(${turn} 1)`);

    shadow.setAttribute("transform",
      `translate(${sx} ${sy}) rotate(${shadowAngle})`);
    shadow.setAttribute("opacity", shadowOpacity);
  }

  draw();

  // Respect reduced-motion preferences with a static pose.
  if (window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    return;
  }

  let previous;
  function frame(now) {
    if (previous !== undefined) {
      let remaining = Math.min((now - previous) / 1000, 0.05);
      while (remaining > 0) {
        const step = Math.min(remaining, 1 / 240);
        advance(step);
        remaining -= step;
      }
    }
    previous = now;
    draw();
    requestAnimationFrame(frame);
  }

  document.addEventListener("visibilitychange", () => {
    previous = undefined;
  });

  requestAnimationFrame(frame);
})();
